[
    {
        "title": "看清研究对象",
        "description": "题目研究的是球的体积，用字母 $V$ 表示体积，用 $r$ 表示球的半径。",
        "bubbleText": "我们先把问题说清楚：要找的是球里面能装多少空间，也就是体积 $V$。",
        "bubblePos": {
            "x": 250,
            "y": 105
        }
    },
    {
        "title": "确定关键长度",
        "description": "球的大小由半径决定，半径是球心到球面任一点的距离，记作 $r$。",
        "bubbleText": "从球心向外量到球面，这段长度就是半径 $r$，后面所有计算都要用它。",
        "bubblePos": {
            "x": 410,
            "y": 135
        }
    },
    {
        "title": "写出体积关系",
        "description": "球的体积公式为 $V=\\frac{4}{3}\\pi r^3$，其中 $r^3=r\\times r\\times r$。",
        "bubbleText": "半径要连续乘三次，因为体积是立体空间，和三个长度方向有关。",
        "bubblePos": {
            "x": 500,
            "y": 160
        }
    },
    {
        "title": "代入已知数据",
        "description": "若已知球的半径为 $r$，直接代入 $V=\\frac{4}{3}\\pi r^3$；计算时先求 $r^3$，再乘以 $\\frac{4}{3}\\pi$。",
        "bubbleText": "计算有顺序：先算半径的三次方，再乘上 $\\frac{4}{3}\\pi$，这样不容易漏算。",
        "bubblePos": {
            "x": 500,
            "y": 400
        }
    },
    {
        "title": "检查结果",
        "description": "所得结果的单位应为立方单位；把半径代回公式可验证 $V\\div r^3=\\frac{4}{3}\\pi$，因此答案形式正确。",
        "bubbleText": "最后检查两件事：单位要带三次方，而且体积除以 $r^3$ 应该回到 $\\frac{4}{3}\\pi$。",
        "bubblePos": {
            "x": 600,
            "y": 470
        }
    }
]
